__NUXT_JSONP__("/th/teachers", {data:[{details:{slug:"th",pageTitle:"ชั้นเรียนและผู้สอนของ MLI | Mentor Language Institute",pageDescription:"ในหลักสูตรภาษาอังกฤษทั่วไป ผู้เรียนจะได้เรียนรู้ทักษะจากชีวิตประจำวัน เช่น ข้อความจาก Twitter, การพูดของ TED และภาพยนตร์",title:"ชั้นเรียนและผู้สอนของ MLI",image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fmli-student-teachers.jpg",lists:[{title:"ชั้นเรียนที่เน้นทักษะการปฏิบัติ",description:["ในหลักสูตรภาษาอังกฤษทั่วไป ผู้เรียนจะได้เรียนรู้ทักษะจากชีวิตประจำวัน เช่น ข้อความจาก Twitter, การพูดของ TED และภาพยนตร์ \u003Cbr \u002F\u003E การใช้เครื่องมือต่างๆ ช่วยส่งเสริมทักษะด้านต่างๆ เช่นไวยากรณ์ การเขียน การอ่าน คำศัพท์ การฟัง และการพูด","นอกจากนี้หลักสูตรเตรียมสอบ TOEFL®และหลักสูตรเตรียมสอบอื่น ๆ ยังสามารถช่วยผู้เรียนแก้ปัญหาต่างๆได้อีกด้วย"]},{title:"ผู้สอน",description:["นักเรียนกว่า 1,200 คนจบการศึกษาจาก MLI ในแต่ละปี ซึ่งพูดถึงคุณภาพการศึกษาของเรา เรามุ่งมั่นอย่างต่อเนื่องเพื่อพัฒนาทักษะของผู้สอน ผ่านการสังเกตการประเมินผลและการฝึกอบรมการพัฒนาวิชาชีพ"],checklist:[{title:"ข้อกำหนดในการรับสมัคร (สำหรับผู้สอน)",lists:["บัณฑิตวิทยาลัย 4 ปี","มีประสบการณ์อย่างน้อย 3 ปีในฐานะผู้สอน","คุณสมบัติการสอน เช่น TESOL","การทดสอบ เช่น TOEFL®, GMAT®","มีทักษะในการสื่อสารที่ดี","มีความมุ่งมั่นในการสอน"]},{title:"วิธีการเลือก",lists:["ประวัติและประกาศนียบัตร","ผลการทดสอบทักษะทางไวยากรณ์","การสัมภาษณ์","การทดลองสอน"],note:"อัตราการจ้างงานต่ำกว่า 20%"}]},{title:"การฝึกอบรมและประเมินผล",description:["MLI จะประเมินคุณผู้สอนทุก 12 สัปดาห์ จาก 3 ข้อต่อไปนี้"],listType:"decimal",lists:["ผู้เรียนประเมินผู้สอน โดยผลการประเมินต้องไม่ต่ำกว่า 85%","การสังเกตและข้อเสนอแนะการสอนจากทีมนักวิชาการ","การฝึกอบรม การพัฒนาวิชาชีพและฝึกอบรมเพื่อปรับปรุงการสอน"],note:"ผู้บริหารและผู้สอนมุ่งมั่นพัฒนาคุณภาพการศึกษาในทุกๆวัน"}],teachers:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-julie.jpg",name:"Julie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-brian.jpg",name:"Brian"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kelsey.jpg",name:"Kelsey"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shawna.jpg",name:"Shawna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-benjamin.jpg",name:"Benjamin"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-kyle.jpg",name:"Kyle"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-lindsay.jpg",name:"Lindsay"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-leo.jpg",name:"Leo"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-alex.jpg",name:"Alex"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-carl.jpg",name:"Carl"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-shenna.jpg",name:"Shenna"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-bonnie.jpg",name:"Bonnie"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-patrick.jpg",name:"Patrick"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-hubert.jpg",name:"Hubert"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-matt.jpg",name:"Matt"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Maribel.jpg",name:"Maribel"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Joan.jpg",name:"Joan"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Sara.jpg",name:"Sara"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Tom.jpg",name:"Tom"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Fteachers\u002Fteacher-Gannon.jpg",name:"Gannon"}],dir:"\u002Fteachers",path:"\u002Fteachers\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:31.177Z",updatedAt:"2025-05-26T12:06:27.932Z"}}],fetch:{},mutations:void 0});